<script setup lang="ts">
import type { AdminUser, AdminWallet, CheckinEntry, PracticeTrigger } from '../api'
const props=defineProps<{triggers:PracticeTrigger[];rewards:CheckinEntry[];wallets:AdminWallet[];users:AdminUser[]|null;creditEnabled:boolean;busy:boolean}>()
const emit=defineEmits<{search:[query:string];credit:[user:AdminWallet|AdminUser]}>()
const query=ref('')
const shown=computed(()=>(props.users??props.wallets) as (AdminWallet|AdminUser)[])
const labels:Record<string,string>={unclaimed:'未领取',credited:'已记入钱包',none:'无奖励'}
function time(value:string){const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString('zh-CN',{hour12:false})}
</script>
<template><section id="sec-triggers" style="margin-bottom:36px"><details class="card card-collapse" open><summary class="collapse-summary"><h2 class="card-title">每次练习的触发时间记录 <span class="card-subtitle">最近 200 条服务端触发打点</span></h2></summary><div class="collapse-body"><div class="table-wrap" style="max-height:280px"><table class="data-table"><thead><tr><th>用户</th><th>次数</th><th>触发时间</th><th>本轮标识</th></tr></thead><tbody><tr v-if="!triggers.length"><td colspan="4" style="text-align:center">暂无练习触发记录。</td></tr><tr v-for="item in triggers" :key="`${item.user_id}-${item.created_at}`"><td>@{{ item.username }}</td><td>第 {{ item.group_no }} 次</td><td>{{ time(item.created_at) }}</td><td style="font-family:monospace">{{ item.flow_id?`${item.flow_id.slice(0,10)}…`:'—' }}</td></tr></tbody></table></div></div></details></section>
<section id="sec-records" style="margin-bottom:40px"><h2 style="font-size:20px;font-weight:700;margin:0 0 16px">记录查询</h2><div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px"><details class="card card-collapse" open><summary class="collapse-summary"><h3 class="card-title">每日奖励领取记录</h3></summary><div class="collapse-body"><div class="table-wrap" style="max-height:280px"><table class="data-table"><thead><tr><th>日期 / 排名</th><th>用户</th><th>积分</th><th>领取状态</th><th>领取时间</th></tr></thead><tbody><tr v-if="!rewards.length"><td colspan="5" style="text-align:center">暂无站内积分奖励记录。</td></tr><tr v-for="item in rewards" :key="`${item.day}-${item.user_id}`"><td>{{ item.day }} · #{{ item.rank }}</td><td>@{{ item.username }}</td><td>{{ item.amount }} 分</td><td>{{ labels[item.reward_status]||item.reward_status }}</td><td>{{ item.claimed_at||'未领取' }}</td></tr></tbody></table></div></div></details>
<details class="card card-collapse" open><summary class="collapse-summary"><h3 class="card-title">用户积分余额</h3></summary><div class="collapse-body"><p style="font-size:13px;color:var(--text-muted)">{{ creditEnabled?'搜索用户后可增加积分，每次操作均需输入二级密码。':'二级密码尚未配置，暂不能增加积分。' }}</p><form style="display:flex;gap:8px;margin-bottom:16px" @submit.prevent="emit('search',query.trim())"><input v-model="query" class="input-text" type="search" maxlength="128" required aria-label="用户名" placeholder="搜索用户名"><button class="btn-secondary" type="submit" :disabled="busy">搜索</button></form><p v-if="users" style="font-size:12px;color:var(--text-dim)">找到 {{ users.length }} 位用户，最多显示 50 位。</p><div class="table-wrap" style="max-height:280px"><table class="data-table"><thead><tr><th>用户</th><th>站内积分余额</th><th>操作</th></tr></thead><tbody><tr v-if="!shown.length"><td colspan="3" style="text-align:center">没有找到用户。</td></tr><tr v-for="user in shown" :key="user.user_id"><td>@{{ user.username }}</td><td>{{ 'balance' in user?`${user.balance} 积分`:'—' }}</td><td><button class="btn-secondary" type="button" :disabled="busy||!creditEnabled" @click="emit('credit',user)">增加积分</button></td></tr></tbody></table></div></div></details></div></section></template>
